package com.yuegang.zhihui.notification.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.notification.api.NotificationCommand;import java.nio.charset.*;import java.util.*;import org.apache.rocketmq.client.consumer.*;import org.apache.rocketmq.client.consumer.listener.*;
public final class NotificationDomainEventConsumer implements AutoCloseable{private final DefaultMQPushConsumer consumer;public NotificationDomainEventConsumer(String nameserver,String topic,NotificationService service,ObjectMapper json){try{consumer=new DefaultMQPushConsumer("ygh-notification-domain-events");consumer.setNamesrvAddr(nameserver);consumer.subscribe(topic,"TRAINING_ASSIGNED || WALLET_PAYMENT_SUCCEEDED");consumer.setMaxReconsumeTimes(8);consumer.registerMessageListener((MessageListenerConcurrently)(messages,context)->{for(var message:messages){try{@SuppressWarnings("unchecked")Map<String,Object>p=json.readValue(new String(message.getBody(),StandardCharsets.UTF_8),Map.class);String tag=message.getTags(),event=Objects.requireNonNullElse(message.getKeys(),UUID.randomUUID().toString());if("TRAINING_ASSIGNED".equals(tag))service.create(new NotificationCommand(event,text(p,"userId"),"TRAINING_ASSIGNED",Map.of("courseTitle",text(p,"courseTitle"))));else if("WALLET_PAYMENT_SUCCEEDED".equals(tag))service.create(new NotificationCommand(event,text(p,"userId"),"ORDER_PAID",Map.of("referenceId",text(p,"referenceId"))));}catch(Exception e){return ConsumeConcurrentlyStatus.RECONSUME_LATER;}}return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;});consumer.start();}catch(Exception e){throw new IllegalStateException("notification RocketMQ consumer startup failed",e);}}private static String text(Map<String,Object>p,String k){Object v=p.get(k);if(v==null||v.toString().isBlank())throw new IllegalArgumentException("event field missing");return v.toString();}public void close(){consumer.shutdown();}}
